// Fan the batch out to one item per HR row, attaching the per-row PDFs.
// n8n's webhook node nests the POST body under $json.body.
const payload = ($input.first().json && $input.first().json.body) || $input.first().json;
const rows = payload.rows || [];
const batchId = payload.batch_id || new Date().toISOString().replace(/[:.]/g, '-');
return rows.map((r) => {
  const item = {
    json: {
      batch_id: batchId,
      date: new Date().toISOString().slice(0, 10),
      company: r.company || '',
      title: r.title || '',
      hr_name: r.hr_name || '',
      hr_email: r.hr_email || '',
      location: r.location || '',
      subject: r.subject || `Application: ${r.title || ''}`,
      body: r.body || ''
    },
    binary: {}
  };
  if (r.resume && r.resume.content_base64) {
    item.binary.resume = { data: r.resume.content_base64, mimeType: 'application/pdf', fileName: r.resume.filename || 'resume.pdf' };
  }
  if (r.cover && r.cover.content_base64) {
    item.binary.cover = { data: r.cover.content_base64, mimeType: 'application/pdf', fileName: r.cover.filename || 'cover.pdf' };
  }
  return item;
});

// Combine all per-row results into a single response for the app.
const items = $input.all();
const results = items.map((i) => ({
  company: i.json.company,
  hr_email: i.json.hr_email,
  status: i.json.error ? 'failed' : 'sent'
}));
const sent = results.filter((r) => r.status === 'sent').length;
return [{ json: { batch: items[0] ? items[0].json.batch_id : '', sent, failed: results.length - sent, results } }];
